package com.game_manager.gm.workflow; import com.game_manager.gm.notification.*; import io.micrometer.core.instrument.MeterRegistry; import java.time.*; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class WorkflowSlaWorker {private final WorkflowStepRepository steps;private final WorkflowService service;private final WorkflowNotificationGateway notifications;private final Clock clock;private final MeterRegistry metrics;public WorkflowSlaWorker(WorkflowStepRepository s,WorkflowService service,WorkflowNotificationGateway n,Clock c,MeterRegistry m){steps=s;this.service=service;notifications=n;clock=c;metrics=m;}
 @Scheduled(fixedDelayString="${app.workflow.sla-poll-millis:60000}")@Transactional public void process(){Instant now=clock.instant();for(WorkflowStep step:steps.findByStatusAndReminderAtBeforeAndRemindedAtIsNull(StepStatus.ACTIVE,now)){step.setRemindedAt(now);service.recipients(step).forEach(id->notifications.send(step.getId(),id,NotificationType.WORKFLOW_REMINDER,"Workflow podsetnik",step.getInstance().getTitle()));metrics.counter("gmanager.workflow.sla","event","reminder").increment();}for(WorkflowStep step:steps.findByStatusAndDueAtBefore(StepStatus.ACTIVE,now)){if(step.getInstance().isEscalated())continue;WorkflowSchema.Step definition=service.schema(step.getInstance().getDefinitionVersion()).step(step.getStepKey());String role=definition.escalationRole()==null?"OWNER":definition.escalationRole();step.setAssigneeId(null);step.setAssigneeRole(role);step.getInstance().setEscalated(true);service.recipients(step).forEach(id->notifications.send(step.getId(),id,NotificationType.WORKFLOW_ESCALATED,"Workflow je eskaliran",step.getInstance().getTitle()));metrics.counter("gmanager.workflow.sla","event","escalation").increment();}}}
